@gene('s4', 'how much closer a step brings me to the goals (cached field and own value, refreshed if I moved); unreachable is no progress; penalise entering danger, reward leaving it')
def progress(t: Tile) -> Num:
    p = me().pos
    here = HERE
    if not valid(HERE_T) or dist(p, HERE_T) != 0:
        here = at(GF, p)
    there = at(GF, t)
    if here >= 1000000 or there >= 1000000:
        return 0
    d = here - there
    inside = p in DANGER
    if t in DANGER:
        if inside:
            return d - 1
        return d - 2
    if inside:
        return d + 1
    return d
